-- Import exact authored Chapter 1–8 content from feature/deep-dive-engine-v1
-- Source: repo content.js (GitHub SHA a168d4481190998931dc06b8981e06e851057cd7).
-- Authored and reviewed separately from 119 draft outlines.
with authored(chapter_number,title,setting,narrative,prompt,choices,takeaway,transition_text,is_independent_mastery,ending_variants) as (
 values
(1,'The Invitation','Chapter 1 · Friday evening','Jack''s mother has planned Christmas breakfast at her home. Jill has quietly pictured their first Christmas morning at home. Both people are excited—and neither knows how much the tradition matters to the other.',NULL,NULL,'Different hopes do not mean opposing teams. Curiosity comes before the calendar.','Later that night, Jill brings up their Christmas plans.',false,NULL),
(2,'What Matters Here?','Chapter 2 · At the kitchen table','Jill says, ''I''d love Christmas morning to be ours this year.'' Jack feels a flash of worry about disappointing his mother. Jill notices him go quiet.','What should Jack say next?','[{"text":"Tell me what Christmas morning at home means to you.","impact":"Jill relaxes a little. Jack still has concerns, but they now have a conversation rather than competing declarations.","coach":"Gottman''s curiosity and a response to a bid for connection create room for both perspectives.","quality":2},{"text":"My mom expects us there; this really isn''t up for debate.","impact":"Jill feels dismissed. She stops offering ideas, and the distance grows.","coach":"Certainty skips over a partner''s bid. A repair would begin with acknowledging that dismissal.","quality":0},{"text":"Fine. We''ll stay home, but you can explain it to Mom.","impact":"The words sound like agreement, but the responsibility has been pushed onto Jill.","coach":"Compliance with resentment is not joint decision-making. Jack still needs to own his part.","quality":0},{"text":"I want some time to think. Can we talk again after dinner?","impact":"Jill is uncertain, but Jack returns later as promised and can participate more calmly.","coach":"A time-out can help when it includes a concrete promise to return to the conversation.","quality":1},{"text":"I''m worried my mother will be hurt. Can we find a way to honor both traditions?","impact":"Jack makes his fear visible without putting it on Jill to fix.","coach":"Differentiation means expressing a genuine concern without surrendering a shared decision.","quality":2},{"text":"Why does your family always have to change everything?","impact":"The discussion turns defensive, though Jill says she only wants to talk about their own morning.","coach":"Global blame obscures the actual request. Name the fear rather than attributing motives.","quality":0}]'::jsonb,NULL,NULL,false,NULL),
(3,'The Real Meaning','Chapter 3 · A quieter conversation','Jill explains that she isn''t trying to take Jack away from his family. She wants the two of them to build memories that belong to their marriage. Jack realizes he has been trying to prevent someone else''s disappointment before listening to his wife.',NULL,NULL,'Aron''s work on shared new experiences suggests that building a tradition together can deepen connection. It''s not a replacement for loving extended family.','They sketch a plan: Christmas morning at home, then alternating grandparent dinners.',false,NULL),
(4,'A Plan of Their Own','Chapter 4 · Making the calendar','They agree: Christmas morning belongs to their home, and grandparent dinners will alternate, starting with Jill''s mother this year. Jack remembers he promised his own mother they''d always come for breakfast.','How should Jack handle that old promise?','[{"text":"Own the promise and tell Jill he will personally explain the new plan.","impact":"Jill feels like a teammate. Jack prepares to have an uncomfortable but honest conversation.","coach":"Owning one''s commitment and communicating a shared decision is a differentiated response.","quality":2},{"text":"Ask Jill to call his mother because she proposed staying home.","impact":"Jill reluctantly agrees, but feels she will be blamed for the decision.","coach":"Delegating the hard conversation can create an unfair alliance against a partner.","quality":0},{"text":"Say nothing and hope his mother forgets about breakfast.","impact":"The short-term tension disappears, but the surprise later is likely to hurt everyone.","coach":"Avoidance protects immediate comfort but often makes a future repair harder.","quality":0},{"text":"Call his mother and explain that Jill won''t let them come.","impact":"His mother becomes angry at Jill. Jack has disguised the couple''s joint choice.","coach":"Speak as a ''we'' when a decision belongs to both people. Blame erodes trust.","quality":0},{"text":"Ask Jill if they can agree on exactly what they''ll say before calling.","impact":"They find language that respects both families without bargaining away the decision.","coach":"Shared planning supports connection while allowing one spouse to hold a boundary.","quality":2},{"text":"Reconsider everything because upsetting his mother feels unbearable.","impact":"Jill hears that agreement may disappear whenever family pressure arrives.","coach":"Discomfort is real, but it does not have to control a jointly made decision.","quality":1}]'::jsonb,NULL,NULL,false,NULL),
(5,'The First Phone Call','Chapter 5 · Saturday afternoon','Jack calls his mother. He tells her they won''t attend breakfast this year. She''s disappointed and reminds him how important Christmas morning has always been. Jack feels the pull to fix her feelings immediately.',NULL,NULL,'A loving boundary leaves room for another person''s feelings. Respect is different from taking responsibility for their disappointment.','His mother calls back that evening, upset.',false,NULL),
(6,'Pressure on the Line','Chapter 6 · Saturday evening','Jack''s mother says she has already set out the special breakfast dishes. Jill overhears the conversation and starts to worry that Jack will resent her. Jack can notice that worry without making Jill responsible for the call.',NULL,NULL,'A relationship can hold a difficult feeling without turning a partner into the problem. A gentle check-in is often a stronger bid than withdrawing.','His mother''s next words are sharper: ''After all I''ve done, Jill is pulling you away from your family.''',false,NULL),
(7,'The Moment of Choice','Chapter 7 · The independent mastery test','Jack hears his mother blame Jill. He''s angry and embarrassed. Jill is watching him, unsure whether he''ll stand beside their decision or make her defend it. His mother is still on the phone.','What should Jack do now? Choose independently. There is no hint before your decision.','[{"text":"Mom, I understand you''re disappointed. This was our decision, and I won''t let Jill be blamed for it.","impact":"His mother remains upset and ends the call. Jill sees Jack take responsibility without attacking his mother.","coach":"Strong demonstration: joint ownership, a respectful boundary, and differentiation under pressure.","quality":2},{"text":"You always manipulate me with guilt. That''s why nobody wants to visit!","impact":"His mother hangs up feeling attacked. Jill appreciates the intention to defend her but is unsettled by the escalation.","coach":"He defended a boundary through contempt and global blame. Repair would mean apologizing for the attack while keeping the decision intact.","quality":0},{"text":"Jill is the one who wants this, but I have to support her.","impact":"His mother targets Jill more intensely. Jill feels exposed and alone.","coach":"This abandons shared ownership and turns support into a reluctant favor.","quality":0},{"text":"I''m not doing this on the phone right now. We''ll talk when we''re calmer.","impact":"He ends the call without escalation. Later he must follow through and clearly state the couple''s decision.","coach":"A bounded pause can help. It demonstrates partial mastery only if followed by respectful ownership.","quality":1},{"text":"You''re right, Mom. We''ll come to breakfast after all.","impact":"His mother is relieved, but Jill finds out their agreement was changed without her.","coach":"The immediate pressure ended by sacrificing joint decision-making.","quality":0},{"text":"I love you, Mom, and I''m looking forward to seeing you later. Christmas morning will be at our house this year.","impact":"His mother sounds hurt. Jack stays kind, consistent, and accountable for the decision.","coach":"Strong demonstration: warmth without surrendering the boundary or blaming Jill.","quality":2}]'::jsonb,NULL,NULL,true,NULL),
(8,'A New Tradition','Chapter 8 · Christmas morning','Christmas arrives quietly. Their morning is imperfect: the cinnamon rolls burn, the phone rings twice, and Jack is still a little sad his mother is disappointed. Jack and Jill laugh at the ruined breakfast and start a tradition that belongs to them. Later, they visit Jill''s family as planned. The family tension hasn''t magically vanished, but they''ve learned to face it side by side.',NULL,NULL,'A satisfying ending need not be a perfect one. Partnership grows through repeated choices, ordinary repair, and moments of shared discovery.','Complete this Deep Dive to add the eighth crossing to your threefold cord.',false,'["Christmas morning belongs to Jack and Jill''s home, as they agreed. The cinnamon rolls burn, and his mother is still disappointed. Jack checks on Jill and they laugh over breakfast, knowing holding a boundary doesn''t erase other people''s feelings.","Christmas morning at home feels quieter than either hoped. Jack''s sharp words on the phone hang over the day. He apologizes to his mother for the insult without withdrawing the shared plan, and tells Jill that defending her should not mean escalating conflict. The repair has begun, but trust needs follow-through.","Jack and Jill stay home for Christmas morning, but Jill feels exposed after being blamed. Jack admits he made her carry a decision they had made together. He offers to correct that with his mother. Their morning isn''t magically repaired, yet they''re finally naming the real hurt.","Jack follows through on the promised second conversation before Christmas. His mother remains disappointed but hears a clear, kind boundary. Jill appreciates the follow-through. Their quiet morning is imperfect, and progress depends on repeating that choice next time.","Jack and Jill go to his mother''s breakfast after he changed their plan alone. Jill is hurt. Later, Jack acknowledges that he let pressure undo a joint decision and listens instead of demanding instant forgiveness. They agree to revisit the next holiday together. Repair is possible, not automatic.","Jack and Jill spend Christmas morning at home, keeping their shared plan. His mother remains sad, but Jack is both warm and clear. After the cinnamon rolls burn, he and Jill laugh and begin a small tradition of their own. It isn''t perfect, but it belongs to them."]'::jsonb)
)
insert into public.deep_dive_chapters
(story_id,chapter_number,title,setting,narrative,prompt,choices,takeaway,transition_text,is_independent_mastery,ending_variants)
select s.id,a.chapter_number,a.title,a.setting,a.narrative,a.prompt,a.choices,
 a.takeaway,a.transition_text,a.is_independent_mastery,a.ending_variants
from authored a
cross join public.deep_dive_stories s
where s.slug='christmas-tug-of-war' and s.story_version=1
on conflict (story_id,chapter_number) do nothing;
